  F.semi = await font([{ family: 'Inter', style: 'Semi Bold' }, { family: 'Inter', style: 'SemiBold' }, F.med]);
  F.bold = await font([{ family: 'Inter', style: 'Bold' }, F.semi]);
  F.serif = await font([{ family: 'Instrument Serif', style: 'Regular' }, { family: 'Playfair Display', style: 'Regular' }, F.reg]);
