const inst = (name, fn, w, h) => safe(name, fn, w, h);
const stat = (label, value) => inst('Stat tile', () => { const i = C.stat.comp.createInstance(); const p = {}; p[C.stat.label] = label; p[C.stat.value] = String(value); setProps(i, p, [['Label', label], ['Value', String(value)]]); i.name = 'Stat · ' + label; return i; }, 82, 56);
const field = ph => inst('Field', () => { const i = C.field.comp.createInstance(); const p = {}; p[C.field.ph] = ph; setProps(i, p, [['Placeholder', ph]]); return i; }, 160, 52);
const toast = label => inst('Toast', () => { const i = C.toast.comp.createInstance(); const p = {}; p[C.toast.label] = label; setProps(i, p, [['Label', label]]); i.name = 'Toast'; return i; }, 200, 42);
const statusBar = theme => inst('Status bar', () => { const i = C.status.defaultVariant.createInstance(); setProps(i, { Theme: theme }); i.name = 'Status bar'; return i; }, W, 54);
const indicator = theme => inst('Home indicator', () => { const i = C.indicator.defaultVariant.createInstance(); setProps(i, { Theme: theme }); i.name = 'Home indicator'; return i; }, W, 34);
const lockup = () => inst('Logo', () => C.lockup.createInstance(), 200, 28);
const mark = () => inst('Logo mark', () => C.mark.createInstance(), 28, 28);
const segControl = () => inst('Segmented control', () => { const i = C.seg.defaultVariant.createInstance(); i.name = 'Segmented control'; return i; }, 361, 46);
const castGo = () => inst('Cast button', () => C.castGo.createInstance(), 52, 52);
const notifBanner = () => inst('Notification', () => { const i = C.notif.comp.createInstance(); i.name = 'Notification'; return i; }, 377, 76);

// ---------- screen building blocks ----------
function screen(name, bg) {
  const f = figma.createFrame();
  f.name = name; f.resize(W, H); f.clipsContent = true;
  f.fills = [paint(bg)];
  return f;
}
// chrome sits on top and stays put while the content scrolls
function chrome(root, theme, extra) {
  const items = [statusBar(theme), indicator(theme)].concat(extra || []);
  root.appendChild(items[0]); items[0].x = 0; items[0].y = 0;
  root.appendChild(items[1]); items[1].x = 0; items[1].y = H - 34;
  for (const e of items.slice(2)) root.appendChild(e);
  root.numberOfFixedChildren = items.length;
}

function avatar(initials, bg) {
  return frame('Avatar', { w: 34, h: 34, r: 999, bg: bg || 'paper', stroke: 'line', main: 'CENTER', cross: 'CENTER' }, [text(initials, 'Caption/Strong')]);
}
function sectionTitle(title, meta) {
  return row('Section · ' + title, { fill: true, pad: [14, 2, 0, 2], main: 'SPACE_BETWEEN', cross: 'MAX' }, [text(title, 'Title/S'), text(meta, 'Caption', { color: 'muted' })]);
}
function listCard(name, rows) {
  return frame(name, { fill: true, r: 16, bg: 'paper', stroke: 'line', clip: true }, rows);
}
function bar(width, pct, trackKey, trackO, fillKey, h) {
  const t = frame('Track', { dir: 'none', w: width, h: h || 6, r: 99, bg: trackKey, bgo: trackO, clip: true });
  const fillR = rect('Fill', Math.max(1, width * pct), h || 6, fillKey, { r: 99 });
  t.appendChild(fillR); fillR.x = 0; fillR.y = 0;
  return t;
}
function budgetRow(label, left, ofText, pct, over) {
  const r = row('Budget · ' + label, { fill: true, pad: [13, 14], gap: 12, cross: 'CENTER' }, [
    frame('Main', { grow: true, gap: 7 }, [text(label, 'Body/M'), bar(220, Math.min(pct, 1), 'bg', 1, 'ink', 4)]),
    frame('End', { gap: 2, cross: 'MAX' }, [text(left, 'Body/M strong'), text(ofText, 'Caption', { color: 'muted' })]),
  ]);
  r.strokes = [paint('line')]; r.strokeTopWeight = 1; r.strokeBottomWeight = 0; r.strokeLeftWeight = 0; r.strokeRightWeight = 0; r.strokeAlign = 'INSIDE';
  return r;
}

// ---------- screens ----------
function home(o) {
  const root = screen(o.name, 'bg');
  const vibeTile = frame('Stat · Vibe', { w: 145, pad: [10, 12], gap: 3, r: 12, bg: 'white', bgo: 0.06 }, [
    text('Vibe', 'Caption', { color: 'muted-ink' }), text(String(o.vibe), 'Number/S', { color: 'white' }),
    frame('Bar wrap', { pad: [5, 0, 0, 0] }, [bar(121, o.vibe / 100, 'white', 0.12, 'lime', 6)]),
  ]);
  const pet = frame('Pet', { fill: true, h: 214, main: 'CENTER', cross: 'CENTER' }, [ellipse('Ground', 150, 14, 'lime', { o: 0.12 })]);
  add(pet, remy(o.mood, 200));
  const ground = pet.children[0]; ground.layoutPositioning = 'ABSOLUTE'; ground.x = 87; ground.y = 186;

  const castBtn = button('Primary', 'Cast before you pay', { icon: true, fill: true });
  const logLink = row('Log it', { fill: true, h: 40, main: 'CENTER', cross: 'CENTER', gap: 4 }, [text('Already paid?', 'Body/M', { color: 'muted' }), text('Log it', 'Body/M strong')]);
  const how = row('How Spellcheck decides', { fill: true, pad: 16, r: 16, bg: 'paper', stroke: 'line', main: 'SPACE_BETWEEN', cross: 'CENTER' }, [text('How Spellcheck decides', 'Title/S'), icon('back', 18, 'ink')]);
  how.children[1].rotation = 180;
  const av = avatar('JK');
  const em = o.earmark;
  const content = frame('Content', { w: W, pad: [58, 16, 48, 16], gap: 12 }, [
    row('Header', { fill: true, h: 44, main: 'SPACE_BETWEEN', cross: 'CENTER' }, [lockup(), av]),
    frame('Pet stage', { fill: true, bg: 'ink', r: 24, pad: [18, 18, 16, 18], gap: 6 }, [
      row('Stage head', { fill: true, main: 'SPACE_BETWEEN' }, [
        frame('Name', { gap: 6 }, [text('Remy', 'Display/Name', { color: 'white' }), text(o.moodLine, 'Caption', { color: 'muted-ink' })]),
        pill('Lvl ' + o.level, 'Lime'),
      ]),
      pet,
      row('Stats', { fill: true, gap: 8 }, [vibeTile, stat('Charms', o.charms), stat('Streak', o.streak)]),
    ]),
    frame('Balance', { fill: true, bg: 'paper', stroke: 'line', r: 16, pad: 16, gap: 4 }, [
      text('Available to spend', 'Body/M', { color: 'muted' }),
      row('Amount', { cross: 'BASELINE' }, [text(o.balance[0], 'Number/XL'), text(o.balance[1], 'Number/XL', { hex: '#B4B2AA' })]),
      frame('Divider wrap', { fill: true, pad: [10, 0, 6, 0] }, [rect('Divider', 10, 1, 'line', { fill: true })]),
      row('Earmark', { fill: true, gap: 12, cross: 'CENTER' }, [
        frame('Tile', { w: 38, h: 38, r: 12, bg: em.state === 'risk' ? 'ink' : 'lime', main: 'CENTER', cross: 'CENTER' }, [icon('utilities', 18, em.state === 'risk' ? 'lime' : 'ink')]),
        frame('Text', { grow: true, gap: 1 }, [text('Mom sent you money', 'Body/M strong'), text(em.sub, 'Caption', { color: 'muted' })]),
        text(em.amount, 'Body/M strong'),
      ]),
    ]),
    frame('Actions', { fill: true, gap: 4 }, [castBtn, logLink]),
    sectionTitle('Budgets this month', '$738 left'),
    listCard('Budgets', o.budgets.map(b => budgetRow.apply(null, b)).concat([
      (() => { const r = row('Show all', { fill: true, pad: 12, main: 'CENTER' }, [text('Show all 9', 'Body/M strong')]); r.strokes = [paint('line')]; r.strokeTopWeight = 1; r.strokeBottomWeight = 0; r.strokeLeftWeight = 0; r.strokeRightWeight = 0; r.strokeAlign = 'INSIDE'; return r; })(),
    ])),
    sectionTitle('Recent spells', 'Last 7 days'),
    listCard('Recent spells', o.history.map(h => spellRow.apply(null, h))),
    how,
    row('Footer', { fill: true, pad: [10, 0, 0, 0], main: 'CENTER' }, [text('Instant feedback beats hindsight.', 'Caption', { color: 'muted' })]),
  ]);
  settle(content); root.appendChild(content); content.x = 0; content.y = 0;
  root.overflowDirection = 'VERTICAL';
  const extra = [];
  if (o.toast) { const t = toast(o.toast); extra.push(t); }
  chrome(root, 'Dark', extra);
  if (o.toast) { const t = extra[0]; t.x = Math.round((W - t.width) / 2); t.y = H - 34 - 54 - t.height + 42; t.constraints = { horizontal: 'CENTER', vertical: 'MAX' }; }
  return { root: root, cast: castBtn, log: logLink, how: how, avatar: av, content: content };
}

