function whyCard(v, score, reasons, us) {
  const tc = v === 'bad' ? 'white' : 'ink';
  const ring = v === 'good' ? '#CCEB3A' : v === 'meh' ? '#FFFFFF' : '#1A1A18';
  const tw = 325;
  const track = frame('Score track', { dir: 'none', w: tw, h: 14 });
  const zones = [['Bad', 0.4], ['Meh', 0.26], ['Good', 0.34]];
  let x = 0;
  for (const [z, share] of zones) {
    const wz = tw * share - 2;
    const seg = rect('Zone · ' + z, wz, 6, tc, { r: 99, o: z.toLowerCase() === v ? 1 : 0.14 });
    track.appendChild(seg); seg.x = x; seg.y = 4; x += wz + 3;
  }
  const knob = ellipse('Knob', 14, 14, tc, { stroke: undefined });
  knob.strokes = [raw(ring)]; knob.strokeWeight = 3; knob.strokeAlign = 'OUTSIDE';
  track.appendChild(knob); knob.x = Math.max(0, Math.min(tw - 14, tw * score / 100 - 7)); knob.y = 0;
  const zoneLabels = row('Zones', { fill: true }, zones.map(([z, share], i) => frame(z, { w: Math.round(tw * share), cross: i === 2 ? 'MAX' : 'MIN' }, [text(z, 'Micro', { color: tc, o: 0.55 })])));
  const reasonRows = reasons.map(([sign, t]) => row('Reason', { fill: true, gap: 9, cross: 'CENTER' }, [
    frame('Sign', { w: 16, h: 16, r: 999, stroke: tc, sw: 1.5, main: 'CENTER', cross: 'CENTER' }, [text(sign === '+' ? '+' : '−', 'Micro/Sign', { color: tc })]),
    text(t, 'Body/M', { color: tc, fill: true }),
  ]));
  const card = frame('Why card', { fill: true, r: 16, pad: [14, 14, 12, 14], gap: 10, bg: v === 'good' ? 'ink' : v === 'meh' ? 'paper' : 'white', bgo: v === 'good' ? 0.06 : v === 'bad' ? 0.06 : 1, stroke: v === 'meh' ? 'line' : undefined }, [
    row('Why head', { fill: true, main: 'SPACE_BETWEEN', cross: 'BASELINE' }, [
      text('Why', 'Body/M strong', { color: tc }),
      row('Score', { cross: 'BASELINE', gap: 2 }, [text(String(score), 'Number/M', { color: tc }), text('/100', 'Caption', { color: tc, o: 0.55 })]),
    ]),
    frame('Meter', { fill: true, gap: 6 }, [track, zoneLabels]),
    frame('Reasons', { fill: true, gap: 7, pad: [2, 0, 0, 0] }, reasonRows),
    text('Scored on your phone in ' + us + ' µs', 'Caption', { color: tc, o: 0.5 }),
  ]);
  return card;
}

function verdictScreen(o) {
  const bg = o.v === 'good' ? 'lime' : o.v === 'meh' ? 'bg' : 'ink';
  const tc = o.v === 'bad' ? 'white' : 'ink';
  const root = screen(o.name, bg);
  const petArea = frame('Pet', { fill: true, grow: true, main: 'CENTER', cross: 'CENTER' }, [remy(o.mood, 220)]);
  if (o.v === 'good' || o.v === 'bad') {
    const fx = svg(o.v === 'good' ? ASSETS.fx.good : ASSETS.fx.bad, o.v === 'good' ? 'Sparkles' : 'Smoke');
    if (o.v === 'bad') setEffects(fx, [{ type: 'LAYER_BLUR', radius: 12, visible: true }]);
    behind(petArea, fx);
  }
  const buttons = o.actions.map(a => button(a[0], a[1], { fill: true }));
  const content = frame('Content', { w: W, h: H, pad: [62, 20, 40, 20], gap: 0 }, [
    row('Top', { fill: true, main: 'SPACE_BETWEEN', cross: 'CENTER' }, [
      text(o.mode, 'Label/Caps', { color: tc, o: 0.7 }),
      row('Spellcheck', { gap: 6, cross: 'CENTER' }, [icon('wand', 13, tc), text('Spellcheck', 'Label/Caps', { color: tc, o: 0.7 })]),
    ]),
    frame('Purchase', { fill: true, gap: 2, pad: [18, 0, 0, 0] }, [text(o.item, 'Body/L', { color: tc, o: 0.72 }), text(o.amount, 'Number/L', { color: tc })]),
    petArea,
    frame('Verdict', { fill: true, gap: 8 }, [text(o.headline, 'Display/Verdict', { color: tc, name: 'Headline' }), text(o.msg, 'Body/L', { color: tc, fill: true, name: 'Message' })]),
    frame('Why wrap', { fill: true, pad: [18, 0, 0, 0] }, [whyCard(o.v, o.score, o.reasons, o.us)]),
    row('Actions', { fill: true, gap: 8, pad: [14, 0, 0, 0] }, buttons),
  ]);
  // the pet area sizes the screen: it soaks up whatever height is left
  try { petArea.minHeight = 160; } catch (e) { /* min sizes need a recent Figma */ }
  settle(content); root.appendChild(content); content.x = 0; content.y = 0;
  chrome(root, o.v === 'bad' ? 'Light' : 'Dark');
  return { root: root, buttons: buttons };
}

